'use client'
import { useEffect, useId, useRef, type FocusEvent, type PointerEvent, type ReactNode } from 'react'
import { PopoverPanel } from '@/react/components/ui/PopoverPanel'
import { usePopover, type Align, type Side } from '@/react/hooks/usePopover'

// More about a link, shown while the pointer rests on it: Menu's square panel, 12px in, opened after the copy
// tooltip's 300ms wait and, on keyboard focus, at once. The pointer can cross into the card to select or follow what
// is in it; leaving both closes it after a short grace. It is a preview, never the only way to the content: on touch
// the link just works. Wrap one link; the card is the `card` prop.
export interface HoverCardProps { side?: Side, align?: Align, width?: string, card?: ReactNode, children?: ReactNode }

const WAIT = 300
const GRACE = 120

export function HoverCard({ side = 'bottom', align = 'start', width = '280px', card, children }: HoverCardProps) {
  const pop = usePopover({ side, align, gap: 6, sticky: true })
  const id = `card-${useId()}`
  const root = useRef<HTMLSpanElement | null>(null)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

  useEffect(() => {
    const trigger = root.current?.firstElementChild as HTMLElement | null
    pop.anchor.current = trigger
    trigger?.setAttribute('aria-describedby', id)
  }, [id]) // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => () => clearTimeout(timer.current), [])

  function enter(event: PointerEvent) {
    if (event.pointerType !== 'mouse') return
    clearTimeout(timer.current)
    // ds-latency: the wait keeps a passing pointer from opening it.
    if (!pop.open) timer.current = setTimeout(() => void pop.show(), WAIT)
  }
  function leave(event: PointerEvent) {
    if (event.pointerType !== 'mouse') return
    clearTimeout(timer.current)
    // ds-latency: a grace to cross the gap into the card.
    timer.current = setTimeout(() => pop.hide(), GRACE)
  }
  function focus(event: FocusEvent) {
    if ((event.target as HTMLElement).matches(':focus-visible')) void pop.show({ keyboard: true })
  }
  function blur(event: FocusEvent) {
    const next = event.relatedTarget as Node | null
    if (!next || !pop.panel.current?.contains(next)) pop.hide()
  }
  return (
    <>
      <span data-ds="hover-card" ref={root} className="inline-flex" onPointerEnter={enter} onPointerLeave={leave} onFocus={focus} onBlur={blur}>
        {children}
      </span>
      <PopoverPanel data-ds="hover-card" id={id} pop={pop} className="p-3" style={{ width }} onPointerEnter={enter} onPointerLeave={leave}>
        {card}
      </PopoverPanel>
    </>
  )
}

export default HoverCard

import { html, nothing, type PropertyValues } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import { boxOf, PopoverController, popoverStyles, within, type Align, type Side } from '@/elements/lib/popover'
import styles from 'virtual:tw'

// HoverCard.vue as <conare-hover-card>: more about a link, shown while the pointer rests on it: Menu's square panel,
// 12px in, opened after the copy tooltip's 300ms wait and, on keyboard focus, at once. The pointer can cross into the
// card to select or follow what is in it; leaving both closes it after a short grace. It is a preview, never the only
// way to the content: on touch the link just works. Wrap one link; the card is the `card` slot. Inside a paragraph, put
// the card in a <template slot="card"> (a <div> or <p> there would end the paragraph): the element moves its content
// into a <div slot="card"> as it connects.
const WAIT = 300
const GRACE = 120

/**
 * @summary More about a link, shown while the pointer rests on it.
 * @slot - One link.
 * @slot card - What the card shows (an element, or a <template slot="card">).
 */
export class HoverCard extends DsElement {
	static styles = [DsElement.styles, popoverStyles, styles]
	static properties = { side: {}, align: {}, width: {} }

	side: Side = 'bottom'
	align: Align = 'start'
	width = '280px'
	private timer?: ReturnType<typeof setTimeout>
	private pop = new PopoverController(this, {
		gap: 6,
		sticky: true,
		anchor: () => boxOf([...this.children].find((c) => !c.hasAttribute('slot'))),
		panel: () => this.renderRoot.querySelector<HTMLElement>('.ds-pop'),
	})

	private enter = (event: PointerEvent) => {
		if (event.pointerType !== 'mouse') return
		clearTimeout(this.timer)
		// ds-latency: the wait keeps a passing pointer from opening it.
		if (!this.pop.open) this.timer = setTimeout(() => void this.pop.show(), WAIT)
	}
	private leave = (event: PointerEvent) => {
		if (event.pointerType !== 'mouse') return
		clearTimeout(this.timer)
		// ds-latency: a grace to cross the gap into the card.
		this.timer = setTimeout(() => this.pop.hide(), GRACE)
	}
	private onFocusIn = (event: FocusEvent) => {
		if ((event.composedPath()[0] as Element).matches(':focus-visible')) void this.pop.show({ keyboard: true })
	}
	private onFocusOut = (event: FocusEvent) => {
		const next = event.relatedTarget as Node | null
		if (!next || !within(this.renderRoot.querySelector('.ds-pop'), next)) this.pop.hide()
	}

	connectedCallback() {
		super.connectedCallback()
		const template = this.querySelector<HTMLTemplateElement>(':scope > template[slot="card"]')
		if (template) {
			const card = document.createElement('div')
			card.slot = 'card'
			card.append(template.content.cloneNode(true))
			template.replaceWith(card)
		}
	}
	disconnectedCallback() {
		super.disconnectedCallback()
		clearTimeout(this.timer)
	}
	protected willUpdate() {
		this.pop.configure({ side: this.side, align: this.align })
	}

	render() {
		const panel = this.pop.rendered
			? html`<div data-ds="hover-card" popover="manual" class="ds-pop p-3" data-side=${this.pop.pos.side} ?data-instant=${this.pop.instant} ?data-placed=${this.pop.pos.placed} style=${this.pop.style(`width: ${this.width}`)} @pointerenter=${this.enter} @pointerleave=${this.leave}><slot name="card"></slot></div>`
			: nothing
		return html`<span data-ds="hover-card" class="inline-flex" @pointerenter=${this.enter} @pointerleave=${this.leave} @focusin=${this.onFocusIn} @focusout=${this.onFocusOut}><slot></slot></span>${panel}`
	}
}

define('hover-card', HoverCard)
